#include "animation_layer_export.h"
#include "document_snapshot.h"
#include <fstream>
#include <iostream>
using namespace moon;
void check(bool v,const char* s){if(!v)throw std::runtime_error(s);}
std::vector<std::uint8_t> read(const std::filesystem::path& p){std::ifstream f(p,std::ios::binary);return {(std::istreambuf_iterator<char>(f)),{}};}
std::vector<std::uint8_t> encode(const Document& d,StaticImageExportOptions o,int f){o.automatic=f==4;if(f==5)return encodeStaticImageJpeg(d,o).bytes;if(f==3)return encodeStaticImageSvg(d,o).bytes;if(f==2)return encodeStaticImageIco(d,o).bytes;if(f==1)return encodeStaticImageBmp(d,o).bytes;return encodeStaticImagePng(d,o).png;}
int main(){try{
 Document d(6,4);d.beginStroke({0,0},0xff0000ff);d.commitStroke();d.addFrame();d.beginStroke({2,1},0xff00ff00);d.commitStroke();const auto bottom=d.layer().id;d.addLayer();d.beginStroke({4,2},0x80ff0000);d.commitStroke();d.setLayerOpacity(.5);const auto middle=d.layer().id;d.addLayer();d.setLayerVisible(false);const auto hidden=d.layer().id;d.markSaved();const auto history=d.historySize(),revision=d.revision();const auto frame=d.frame().id;
 const auto owned=std::filesystem::path("static-layers-core-owned")/std::to_string(std::chrono::steady_clock::now().time_since_epoch().count());std::filesystem::create_directories(owned);
 StaticImageExportOptions image;image.trim=true;image.layerId=bottom;auto single=encodeStaticImagePng(d,image);check(single.width==1&&single.height==1&&single.pixels==std::vector<Pixel>{0xff00ff00},"Current active frame and individual bounds");image.trimCommon=true;single=encodeStaticImagePng(d,image);check(single.width==3&&single.height==2&&single.pixels.front()==0xff00ff00,"Original active-frame common bounds");image.trimCommon=false;image.layerId=hidden;single=encodeStaticImagePng(d,image);check(single.width==6&&single.height==4&&std::all_of(single.pixels.begin(),single.pixels.end(),[](auto p){return p==0;}),"Hidden target stays transparent with full canvas fallback");
 DocumentSnapshot snapshot(d);while(!snapshot.advance(d,std::chrono::steady_clock::now()+std::chrono::seconds(1))){}auto copy=snapshot.finish();AnimationLayerExportOptions options;options.staticImage=true;options.image.trim=true;options.image.scalePercent=150;options.image.protection=ExportProtection::Blur;
 for(int format=0;format<6;++format){options.format=format;options.image.trimCommon=format%2;auto n=std::to_string(format);auto plan=*planStaticLayerExport(d,"deleted",owned,U"format-"+std::u32string(n.begin(),n.end()),format,{});check(plan.layerIds==std::vector<std::string>({bottom,middle,hidden}),"Static invalid target bottom-to-top fallback");check(writeAnimationLayerExport(copy,options,plan)==3,"Static batch writes");for(std::size_t i=0;i<plan.paths.size();++i){auto isolated=options.image;isolated.layerId=plan.layerIds[i];check(read(plan.paths[i])==encode(d,isolated,format),"Batch routes unchanged static encoder");}}
 auto plan=*planStaticLayerExport(d,{},owned,U"cancel",0,{});options.format=0;bool stop=false;check(writeAnimationLayerExport(d,options,plan,[&]{return stop;},[&](auto n,auto){stop=n==1;})==1&&std::filesystem::exists(plan.paths[0])&&!std::filesystem::exists(plan.paths[1]),"Static partial cancellation preserves committed output");check(d.historySize()==history&&d.revision()==revision&&!d.dirty()&&d.frame().id==frame&&d.layer().id==hidden,"Static batch preserves document");std::cout<<"Static six-format batch, current frame, trim scopes, hidden fallback and cancellation passed\n";return 0;
}catch(const std::exception& e){std::cerr<<e.what()<<"\n";return 1;}}
